(function(){'use strict';var header=document.querySelector('.go-header--471');if(!header){return;}
var compactAt=120;var expandAt=12;var frame=0;var isCompact=header.classList.contains('is-od471-scrolled');function sync(){frame=0;var y=Math.max(0,window.scrollY||window.pageYOffset||0);var next=isCompact;if(!isCompact&&y>compactAt){next=true;}else if(isCompact&&y<expandAt){next=false;}
if(next!==isCompact){isCompact=next;header.classList.toggle('is-od471-scrolled',isCompact);}}
function schedule(){if(frame){return;}
frame=window.requestAnimationFrame(sync);}
(function markCurrentSection(){var current=(window.location.pathname||'/').replace(/\/+$/,'')||'/';var links=header.querySelectorAll('.go-header__sections-list a');for(var i=0;i<links.length;i+=1){try{var path=(new URL(links[i].href,window.location.href).pathname||'/').replace(/\/+$/,'')||'/';var exactHome=path==='/'&&current==='/';var section=path!=='/'&&(current===path||current.indexOf(path+'/')===0);if(exactHome||section){links[i].setAttribute('aria-current','page');}else{links[i].removeAttribute('aria-current');}}catch(error){}}}());window.addEventListener('scroll',schedule,{passive:true});window.addEventListener('resize',schedule,{passive:true});window.addEventListener('pageshow',schedule);sync();}());(function(){'use strict';var buttons=Array.prototype.slice.call(document.querySelectorAll('[data-go-scored-copy]'));if(!buttons.length){return;}
function fallbackCopy(value){var area=document.createElement('textarea');area.value=value;area.setAttribute('readonly','readonly');area.style.position='fixed';area.style.opacity='0';document.body.appendChild(area);area.select();try{document.execCommand('copy');}catch(error){}
document.body.removeChild(area);}
buttons.forEach(function(button){button.addEventListener('click',function(){var url=button.getAttribute('data-share-url')||window.location.href;var original=button.getAttribute('data-original-label')||button.textContent;button.setAttribute('data-original-label',original);var done=function(){button.textContent='Copiado';window.setTimeout(function(){button.textContent=original;},1600);};if(navigator.clipboard&&window.isSecureContext){navigator.clipboard.writeText(url).then(done).catch(function(){fallbackCopy(url);done();});}else{fallbackCopy(url);done();}});});})();
